async def act(page):
    """
    From the current Shopping Cart Price Rules listing, create a new rule named
    "Mother's Day Sale" that gives a $15 fixed discount on checkout for all
    customers.

    Approach summary (keeps accessibility selectors):
    - Click the "Add New Rule . . ." button located inside the listing's header row.
    - Wait for the rule edit page to load.
    - Fill Rule Name and Description.
    - Set Status to Active.
    - Ensure all customer group checkboxes are checked.
    - Open the Actions tab and set Apply to a fixed cart discount and set Discount Amount to 15.
    - Click Save (Save Rule) as the final action that navigates away.

    The knowledge-base helpers are dashboard/export helpers (get_dashboard_summary,
    export_orders_csv, etc.) and do not help with creating a shopping cart price rule,
    so none are used.
    """
    import asyncio

    async def count(locator):
        try:
            return await locator.count()
        except Exception:
            return 0

    async def safe_click(locator, timeout_ms=800):
        if await count(locator) > 0:
            await locator.first.click()
            await page.wait_for_timeout(timeout_ms)
            return True
        return False

    async def safe_fill(locator, value):
        if await count(locator) > 0:
            await locator.first.fill(value)
            await page.wait_for_timeout(200)
            return True
        return False

    async def safe_select_option(locator, *, label=None, value=None):
        if await count(locator) > 0:
            try:
                if label is not None:
                    await locator.first.select_option(label=label)
                elif value is not None:
                    await locator.first.select_option(value=value)
                else:
                    return False
                await page.wait_for_timeout(200)
                return True
            except Exception:
                return False
        return False

    # 0) Short pause in case the listing is still finishing rendering or a transient modal is present
    await page.wait_for_timeout(500)

    # 1) Click the Add New Rule button using a full parent->child get_by_role path
    add_clicked = False
    header_row = page.get_by_role("row", name="Shopping Cart Price Rules Add New Rule . . .")
    if await count(header_row) > 0:
        add_btn = header_row.get_by_role("button", name="Add New Rule . . .")
        add_clicked = await safe_click(add_btn, timeout_ms=1200)

    # fallback: try any button that contains 'Add New' text (scoped to table to reduce ambiguity)
    if not add_clicked:
        try:
            tables = page.get_by_role("table")
            tcount = await count(tables)
            for i in range(tcount):
                tbl = tables.nth(i)
                btns = tbl.get_by_role("button")
                bcount = await count(btns)
                for j in range(bcount):
                    b = btns.nth(j)
                    try:
                        txt = (await b.inner_text()).strip()
                    except Exception:
                        txt = ""
                    if 'add new' in txt.lower():
                        await b.click()
                        await page.wait_for_load_state('networkidle')
                        await page.wait_for_timeout(800)
                        add_clicked = True
                        break
                if add_clicked:
                    break
        except Exception:
            pass

    # If Add New didn't open for some reason, try relative navigation to the new-rule path
    if not add_clicked:
        try:
            # common admin relative path for new promo rule; safe relative goto per instructions
            await page.goto('/index.php/admin/promo_quote/new/')
            await page.wait_for_load_state('networkidle')
            await page.wait_for_timeout(800)
            add_clicked = True
        except Exception:
            # if navigation fails, give up (the script attempted all reasonable fallbacks)
            pass

    # 2) Now on the rule creation page: fill main fields
    # Rule Name (try several likely accessible names)
    await safe_fill(page.get_by_role("textbox", name="Rule Name"), "Mother's Day Sale")
    await safe_fill(page.get_by_role("textbox", name="Name"), "Mother's Day Sale")

    # Description
    await safe_fill(page.get_by_role("textbox", name="Description"), "$15 off at checkout for all customers for Mother's Day.")
    # also try generic textbox fallback (first textbox that isn't empty) - be conservative
    try:
        tbs = page.get_by_role('textbox')
        tbcount = await count(tbs)
        if tbcount > 0:
            # try to fill any textbox that contains 'description' in its accessible name
            for i in range(tbcount):
                tb = tbs.nth(i)
                try:
                    name = await tb.get_attribute('name') or ''
                except Exception:
                    name = ''
                try:
                    label_text = await tb.get_attribute('aria-label') or ''
                except Exception:
                    label_text = ''
                if 'description' in (name + label_text).lower():
                    await tb.fill("$15 off at checkout for all customers for Mother's Day.")
                    break
    except Exception:
        pass

    # 3) Set Status = Active
    await safe_select_option(page.get_by_role('combobox', name='Status'), label='Active')
    # fallback: combobox with options that include 'Active'
    try:
        combs = page.get_by_role('combobox')
        ccount = await count(combs)
        for i in range(ccount):
            cb = combs.nth(i)
            # try selecting Active by label if present
            ok = await safe_select_option(cb, label='Active')
            if ok:
                break
    except Exception:
        pass

    # 4) Ensure all customer group checkboxes are checked
    try:
        # Customer group checkboxes are rendered as role='checkbox'
        cboxes = page.get_by_role('checkbox')
        ccount = await count(cboxes)
        for i in range(ccount):
            cb = cboxes.nth(i)
            try:
                checked = await cb.is_checked()
            except Exception:
                checked = False
            if not checked:
                try:
                    await cb.check()
                    await page.wait_for_timeout(120)
                except Exception:
                    # fallback to click if .check() unavailable
                    try:
                        await cb.click()
                        await page.wait_for_timeout(120)
                    except Exception:
                        pass
    except Exception:
        # continue even if we couldn't find or check customer group checkboxes
        await page.wait_for_timeout(200)

    # 5) Open Actions tab to set discount behavior
    actions_tab_clicked = False
    actions_tab = page.get_by_role('tab', name='Actions')
    if await count(actions_tab) > 0:
        try:
            await actions_tab.first.click()
            await page.wait_for_timeout(400)
            actions_tab_clicked = True
        except Exception:
            actions_tab_clicked = False

    if not actions_tab_clicked:
        # fallback: try link or button named Actions
        await safe_click(page.get_by_role('link', name='Actions'), timeout_ms=400)
        await safe_click(page.get_by_role('button', name='Actions'), timeout_ms=400)

    await page.wait_for_timeout(300)

    # 6) Set Apply option to a fixed cart discount (try likely labels)
    apply_labels = [
        'Fixed amount discount for whole cart',
        'Fixed Amount Discount for whole cart',
        'Fixed amount discount',
        'Fixed Amount',
        'Fixed Amount for whole cart',
        'Fixed amount',
    ]
    applied = False
    # prefer combobox named "Apply"
    for lbl in apply_labels:
        applied = await safe_select_option(page.get_by_role('combobox', name='Apply'), label=lbl)
        if applied:
            break
    if not applied:
        # try all comboboxes as fallback
        try:
            combs = page.get_by_role('combobox')
            ccount = await count(combs)
            for i in range(ccount):
                cb = combs.nth(i)
                for lbl in apply_labels:
                    try:
                        ok = await safe_select_option(cb, label=lbl)
                    except Exception:
                        ok = False
                    if ok:
                        applied = True
                        break
                if applied:
                    break
        except Exception:
            pass

    # 7) Fill Discount Amount = 15
    await safe_fill(page.get_by_role('textbox', name='Discount Amount'), '15')
    await safe_fill(page.get_by_role('textbox', name='Discount'), '15')

    # 8) Save the rule — final action which may navigate away
    # Try to locate a Save Rule button in the page header/toolbar
    save_clicked = False
    # Try exact 'Save Rule' button first
    save_clicked = await safe_click(page.get_by_role('button', name='Save Rule'), timeout_ms=1200)

    if not save_clicked:
        # Try generic 'Save' or 'Save and Continue Edit'
        save_clicked = await safe_click(page.get_by_role('button', name='Save'), timeout_ms=1200)
    if not save_clicked:
        save_clicked = await safe_click(page.get_by_role('button', name='Save and Continue Edit'), timeout_ms=1200)

    if not save_clicked:
        # As a last resort click any visible button whose inner text contains 'save'
        try:
            btns = page.get_by_role('button')
            bcount = await count(btns)
            for i in range(bcount):
                b = btns.nth(i)
                try:
                    txt = (await b.inner_text() or '').strip().lower()
                except Exception:
                    txt = ''
                if 'save' in txt:
                    try:
                        await b.click()
                        save_clicked = True
                        break
                    except Exception:
                        continue
        except Exception:
            pass

    # wait after save/navigation
    await page.wait_for_timeout(1200)

