async def act(page):
    """
    From the current Shopping Cart Price Rules listing, create a new rule named
    "Mother's Day Sale" that gives a $15 fixed discount on checkout for all
    customers.

    Approach summary (keeps accessibility selectors):
    - Click the "Add New Rule . . ." button located inside the listing's header row.
    - Wait for the rule edit page to load.
    - Fill Rule Name and Description.
    - Set Status to Active.
    - Ensure all customer group checkboxes are checked.
    - Open the Actions tab and set Apply to a fixed cart discount and set Discount Amount to 15.
    - Click Save (Save Rule) as the final action that navigates away.

    The knowledge-base helpers are dashboard/export helpers (get_dashboard_summary,
    export_orders_csv, etc.) and do not help with creating a shopping cart price rule,
    so none are used.
    """
    import asyncio

    async def count(locator):
        try:
            return await locator.count()
        except Exception:
            return 0

    async def safe_click(locator, timeout_ms=800):
        if await count(locator) > 0:
            await locator.first.click()
            await page.wait_for_timeout(timeout_ms)
            return True
        return False

    async def safe_fill(locator, value):
        if await count(locator) > 0:
            await locator.first.fill(value)
            await page.wait_for_timeout(200)
            return True
        return False

    async def safe_select_option(locator, *, label=None, value=None):
        if await count(locator) > 0:
            try:
                if label is not None:
                    await locator.first.select_option(label=label)
                elif value is not None:
                    await locator.first.select_option(value=value)
                else:
                    return False
                await page.wait_for_timeout(200)
                return True
            except Exception:
                return False
        return False

    # 0) Short pause in case the listing is still finishing rendering or a transient modal is present
    await page.wait_for_timeout(500)

    # 1) Click the Add New Rule button using a full parent->child get_by_role path
    add_clicked = False
    header_row = page.get_by_role("row", name="Shopping Cart Price Rules Add New Rule . . .")
    if await count(header_row) > 0:
        add_btn = header_row.get_by_role("button", name="Add New Rule . . .")
        add_clicked = await safe_click(add_btn, timeout_ms=1200)

    # fallback: try any button that contains 'Add New' text (scoped to table to reduce ambiguity)
    if not add_clicked:
        try:
            tables = page.get_by_role("table")
            tcount = await count(tables)
            for i in range(tcount):
                tbl = tables.nth(i)
                btns = tbl.get_by_role("button")
                bcount = await count(btns)
                for j in range(bcount):
                    b = btns.nth(j)
                    try:
                        txt = (await b.inner_text()).strip()
                    except Exception:
                        txt = ""
                    if 'add new' in txt.lower():
                        await b.click()
                        await page.wait_for_load_state('networkidle')
                        await page.wait_for_timeout(800)
                        add_clicked = True
                        break
                if add_clicked:
                    break
        except Exception:
